package com.qa.tests;

import io.github.bonigarcia.wdm.WebDriverManager;
import org.openqa.selenium.WebDriver;
import org.openqa.selenium.chrome.ChromeDriver;
import org.openqa.selenium.chrome.ChromeOptions;
import org.testng.Assert;
import org.testng.annotations.*;
import com.qa.pages.HomePagePage;
import com.qa.pages.Page2Page;
import com.qa.pages.Page3Page;
import com.qa.pages.Page4Page;
import com.qa.pages.Page5Page;
import com.qa.pages.Page6Page;
import com.qa.pages.Page7Page;
import com.qa.pages.Page8Page;
import com.qa.pages.Page9Page;
import com.qa.pages.Page10Page;
import com.qa.pages.Page11Page;
import com.qa.pages.Page12Page;
import com.qa.pages.Page13Page;
import com.qa.pages.Page14Page;
import com.qa.pages.Page15Page;
import com.qa.pages.Page16Page;
import com.qa.pages.Page17Page;
import com.qa.pages.Page18Page;
import com.qa.pages.Page19Page;

public class OrangeHRMNavigationandUserManagementWalkthroughTest {
    private WebDriver driver;

    @BeforeClass
    public void setUp() {
        WebDriverManager.chromedriver().setup();
        ChromeOptions options = new ChromeOptions();
        options.addArguments("--headless=new", "--window-size=1280,800");
        driver = new ChromeDriver(options);
    }

    @Test
    public void testOrangeHRMNavigationandUserManagementWalkthroughWorkflow() {
        HomePagePage homepagePage = new HomePagePage(driver);
        Page2Page page2Page = new Page2Page(driver);
        Page3Page page3Page = new Page3Page(driver);
        Page4Page page4Page = new Page4Page(driver);
        Page5Page page5Page = new Page5Page(driver);
        Page6Page page6Page = new Page6Page(driver);
        Page7Page page7Page = new Page7Page(driver);
        Page8Page page8Page = new Page8Page(driver);
        Page9Page page9Page = new Page9Page(driver);
        Page10Page page10Page = new Page10Page(driver);
        Page11Page page11Page = new Page11Page(driver);
        Page12Page page12Page = new Page12Page(driver);
        Page13Page page13Page = new Page13Page(driver);
        Page14Page page14Page = new Page14Page(driver);
        Page15Page page15Page = new Page15Page(driver);
        Page16Page page16Page = new Page16Page(driver);
        Page17Page page17Page = new Page17Page(driver);
        Page18Page page18Page = new Page18Page(driver);
        Page19Page page19Page = new Page19Page(driver);

        // Navigate to entry URL
        homepagePage.open();

        // Step 1: Verify Browser Address Bar
        Assert.assertTrue(homepagePage.verify_browser_address_bar());

        // Step 2: Fill Password Field
        page2Page.fill_password_field("admin123");

        // Step 3: Click Login Button
        page3Page.click_login_button();

        // Step 4: Click Admin Menu Option
        page4Page.click_admin_menu_option();

        // Step 5: Fill System Users Username Input
        page5Page.fill_system_users_username_input("test");

        // Step 6: Verify User Role Dropdown
        Assert.assertTrue(page6Page.verify_user_role_dropdown());

        // Step 7: Verify Status Dropdown
        Assert.assertTrue(page7Page.verify_status_dropdown());

        // Step 8: Click PIM Menu Option
        page8Page.click_pim_menu_option();

        // Step 9: Click Leave Menu Option
        page9Page.click_leave_menu_option();

        // Step 10: Click Time Menu Option
        page10Page.click_time_menu_option();

        // Step 11: Fill Employee Name Field
        page11Page.fill_employee_name_field("Test user emp");

        // Step 12: Click Recruitment Menu Option
        page12Page.click_recruitment_menu_option();

        // Step 13: Click My Info Menu Option
        page13Page.click_my_info_menu_option();

        // Step 14: Click Emergency Contacts Tab
        page14Page.click_emergency_contacts_tab();

        // Step 15: Click Dependents Tab
        page15Page.click_dependents_tab();

        // Step 16: Click Performance Menu Option
        page16Page.click_performance_menu_option();

        // Step 17: Click Dashboard Menu Option
        page17Page.click_dashboard_menu_option();

        // Step 18: Click User Profile Menu
        page18Page.click_user_profile_menu();

        // Step 19: Verify Login Page Container
        Assert.assertTrue(page19Page.verify_login_page_container());
    }

    @AfterClass
    public void tearDown() {
        if (driver != null) {
            driver.quit();
        }
    }
}

