import com.qa.pages.UserManagementSpectrumCloudPage;

public class SpectrumCloudInviteUserWorkflowTest {
    private WebDriver driver;

    @BeforeClass
    public void setUp() {
        WebDriverManager.chromedriver().setup();
        ChromeOptions options = new ChromeOptions();
        options.addArguments("--headless=new", "--window-size=1280,800");
        driver = new ChromeDriver(options);
    }

    @Test
    public void testSpectrumCloudInviteUserWorkflowWorkflow() {
        WelcomebacktoSpectrumCloudPage welcomebacktospectrumcloudPage = new WelcomebacktoSpectrumCloudPage(driver);
        DashboardSpectrumCloudPage dashboardspectrumcloudPage = new DashboardSpectrumCloudPage(driver);
        UserManagementSpectrumCloudPage usermanagementspectrumcloudPage = new UserManagementSpectrumCloudPage(driver);

        // Navigate to entry URL
        welcomebacktospectrumcloudPage.open();

        // Step 1: Verify Spectrum Cloud Login URL
        Assert.assertTrue(welcomebacktospectrumcloudPage.verify_spectrum_cloud_login_url());

        // Step 2: Fill Mobile Number Input
        welcomebacktospectrumcloudPage.fill_mobile_number_input("8122809283");

        // Step 3: Fill Password Input
        welcomebacktospectrumcloudPage.fill_password_input("********");

        // Step 4: Click Login to Dashboard Button
        welcomebacktospectrumcloudPage.click_login_to_dashboard_button();

        // Step 5: Click User Management Sidebar Link
        dashboardspectrumcloudPage.click_user_management_sidebar_link();

        // Step 6: Click Add & Invite Team Members Card
        usermanagementspectrumcloudPage.click_add___invite_team_members_card();

        // Step 7: Click Continue Button (Invite Users Modal)
        usermanagementspectrumcloudPage.click_continue_button__invite_users_modal_();

        // Step 8: Fill Name Input
        usermanagementspectrumcloudPage.fill_name_input("Sow");

        // Step 9: Fill Mobile Number Input
        usermanagementspectrumcloudPage.fill_mobile_number_input("9876543211");

        // Step 10: Fill Email Address Input
        usermanagementspectrumcloudPage.fill_email_address_input("sow@gmail.com");

        // Step 11: Fill Employee No. Input
        usermanagementspectrumcloudPage.fill_employee_no__input("DC45678");

        // Step 12: Fill Designation Input
        usermanagementspectrumcloudPage.fill_designation_input("QA");

        // Step 13: Fill Department Input
        usermanagementspectrumcloudPage.fill_department_input("QA");

        // Step 14: Click Send Invitation Button
        usermanagementspectrumcloudPage.click_send_invitation_button();

        // Step 15: Fill Mobile Number Input
        usermanagementspectrumcloudPage.fill_mobile_number_input("9876543216");

        // Step 16: Click Send Invitation Button
        usermanagementspectrumcloudPage.click_send_invitation_button();

        // Step 17: Verify Invitation Success Notification
        Assert.assertTrue(usermanagementspectrumcloudPage.verify_invitation_success_notification());
    }

    @AfterClass
    public void tearDown() {
        if (driver != null) {
            driver.quit();
        }
    }
}

