import { BasePage } from './BasePage';

export class ParaBankAccountCreatedPage extends BasePage {
  readonly pageUrl: string = 'https://parabank.parasoft.com/parabank/register.htm';
  readonly admin_page_link: Locator;

  constructor(page: Page) {
    super(page);
    this.admin_page_link = this.page.getByText('Admin Page', { exact: true });
  }

  async navigate(): Promise<void> {
    await this.goto(this.pageUrl);
  }

  async click_admin_page_link(): Promise<void> {
    await this.clickElement(this.admin_page_link);
  }
}

import { Page, Locator } from '@playwright/test';
import { BasePage } from './BasePage';

export class ParaBankAdministrationPage extends BasePage {
  readonly pageUrl: string = 'https://parabank.parasoft.com/parabank/admin.htm';
  readonly initialize_database_button: Locator;
  readonly soap_endpoint_url_field: Locator;
  readonly products_link: Locator;

  constructor(page: Page) {
    super(page);
    this.initialize_database_button = this.page.getByText('INITIALIZE', { exact: true });
    this.soap_endpoint_url_field = this.page.getByPlaceholder('Soap Endpoint URL Field');
    this.products_link = this.page.getByText('Products', { exact: true });
  }

  async navigate(): Promise<void> {
    await this.goto(this.pageUrl);
  }

  async click_initialize_database_button(): Promise<void> {
    await this.clickElement(this.initialize_database_button);
  }

  async fill_soap_endpoint_url_field(value: string = 'test@endpoint.om'): Promise<void> {
    await this.fillElement(this.soap_endpoint_url_field, value);
  }

  async click_products_link(): Promise<void> {
    await this.clickElement(this.products_link);
  }
}

import { Page, Locator } from '@playwright/test';
import { BasePage } from './BasePage';

export class SoftwareDevelopmentTestingToolsParasoftPage extends BasePage {
  readonly pageUrl: string = 'https://www.parasoft.com/products/';
  readonly parasoft_products_landing_page: Locator;

  constructor(page: Page) {
    super(page);
    this.parasoft_products_landing_page = this.page.locator('#parasoft_products_landing_page');
  }

  async navigate(): Promise<void> {
    await this.goto(this.pageUrl);
  }

  async verify_parasoft_products_landing_page(): Promise<void> {
    await this.verifyVisible(this.parasoft_products_landing_page);
  }
}

import { test, expect } from '@playwright/test';
import { ParaBankWelcomeOnlineBankingPage } from '../pages/ParaBankWelcomeOnlineBankingPage';
import { ParaBankRegisterforFreeOnlineAccountPage } from '../pages/ParaBankRegisterforFreeOnlineAccountPage';
import { ParaBankAccountCreatedPage } from '../pages/ParaBankAccountCreatedPage';
import { ParaBankAdministrationPage } from '../pages/ParaBankAdministrationPage';
import { SoftwareDevelopmentTestingToolsParasoftPage } from '../pages/SoftwareDevelopmentTestingToolsParasoftPage';

test.describe('ParaBank User Registration and Admin Configuration End-to-End Walkthrough - Playwright TypeScript Suite', () => {
  test('executes all verified sequential steps from walkthrough video', async ({ page }) => {
    const parabankwelcomeonlinebankingPage = new ParaBankWelcomeOnlineBankingPage(page);
    const parabankregisterforfreeonlineaccountPage = new ParaBankRegisterforFreeOnlineAccountPage(page);
    const parabankaccountcreatedPage = new ParaBankAccountCreatedPage(page);
    const parabankadministrationPage = new ParaBankAdministrationPage(page);
    const softwaredevelopmenttestingtoolsparasoftPage = new SoftwareDevelopmentTestingToolsParasoftPage(page);

    // Navigate to initial application URL
    await parabankwelcomeonlinebankingPage.navigate();

    // Step 1: Verify ParaBank Homepage
    await parabankwelcomeonlinebankingPage.verify_parabank_homepage();

    // Step 2: Click Register Link
    await parabankwelcomeonlinebankingPage.click_register_link();

    // Step 3: Fill First Name Input
    await parabankregisterforfreeonlineaccountPage.fill_first_name_input('tesst');

    // Step 4: Fill Street Address Input
    await parabankregisterforfreeonlineaccountPage.fill_street_address_input('123, New York');

    // Step 5: Fill City Input
    await parabankregisterforfreeonlineaccountPage.fill_city_input('US');

    // Step 6: Fill Zip Code Input
    await parabankregisterforfreeonlineaccountPage.fill_zip_code_input('1234566');

    // Step 7: Fill Username Input
    await parabankregisterforfreeonlineaccountPage.fill_username_input('test');

    // Step 8: Fill Password Confirmation Input
    await parabankregisterforfreeonlineaccountPage.fill_password_confirmation_input('test123');

    // Step 9: Click Register Button
    await parabankregisterforfreeonlineaccountPage.click_register_button();

    // Step 10: Click Admin Page Link
    await parabankaccountcreatedPage.click_admin_page_link();

    // Step 11: Click Initialize Database Button
    await parabankadministrationPage.click_initialize_database_button();

    // Step 12: Fill Soap Endpoint URL Field
    await parabankadministrationPage.fill_soap_endpoint_url_field('test@endpoint.om');

    // Step 13: Click Products Link
    await parabankadministrationPage.click_products_link();

    // Step 14: Verify Parasoft Products Landing Page
    await softwaredevelopmenttestingtoolsparasoftPage.verify_parasoft_products_landing_page();

    // Verification check
    await expect(page).not.toHaveURL(/error/i);
  });
});
